/** Cubic ease-out count-up, the mock-up's `animateCounters()`. */
const useCountUp = (target: number, runKey: number, duration = 1000): number => {
  const [value, setValue] = useState(0);

  useEffect(() => {
    let frame = 0;
    let start: number | null = null;

    const step = (timestamp: number) => {
      if (start === null) start = timestamp;
      const progress = Math.min((timestamp - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.round(target * eased));
      if (progress < 1) frame = window.requestAnimationFrame(step);
    };

    frame = window.requestAnimationFrame(step);
    return () => window.cancelAnimationFrame(frame);
  }, [target, runKey, duration]);

  return value;
};

const Counter: React.FC<{ value: number; runKey: number; prefix?: string; suffix?: string; className?: string }> = ({
  value,
  runKey,
  prefix = '',
  suffix = '',
  className,
}) => {
  const current = useCountUp(value, runKey);
  return (
    <span className={className}>
      {prefix}
      {current.toLocaleString('en-US')}
      {suffix}
    </span>
  );
};

const formatTimestamp = (d: Date): string =>
  d
    .toLocaleString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    })
    .replace(',', ' •');

interface LegendDatum {
  label: string;
  value: number;
  color: string;
  // recharts v3 types its `data` prop as an indexable record, so a plain
  // interface is rejected without this.
  [key: string]: string | number;
}

const Legend: React.FC<{ data: LegendDatum[]; compact?: boolean }> = ({ data, compact }) => {
  const total = data.reduce((sum, d) => sum + d.value, 0);
  return (
    <ul className={compact ? 'legend-list compact' : 'legend-list'}>
      {data.map((d) => (
        <li key={d.label}>
          <span className="legend-name">
            <i className="dot" style={{ background: d.color }} />
            {d.label}
          </span>
          <span className="legend-value">
            {d.value} ({total ? Math.round((d.value / total) * 100) : 0}%)
          </span>
        </li>
      ))}
    </ul>
  );
};

const ChartTooltip: React.FC<{ active?: boolean; payload?: any[]; suffix?: string }> = ({
  active,
  payload,
  suffix = '',
}) => {
  if (!active || !payload || !payload.length) return null;
  const point = payload[0];
  const label = point.payload?.label ?? point.name;
  return (
    <div className="chart-tooltip">
      {label}: <strong>{point.value}{suffix}</strong>
    </div>
  );
};

/** Donut sized to fill its wrapper, matching Chart.js `cutout`. */
const Donut: React.FC<{ data: LegendDatum[]; cutout: string; suffix?: string }> = ({ data, cutout, suffix }) => (
  <ResponsiveContainer width="100%" height="100%">
    <PieChart>
      <Pie
        data={data}
        dataKey="value"
        nameKey="label"
        innerRadius={cutout}
        outerRadius="100%"
        startAngle={90}
        endAngle={-270}
        stroke="none"
        isAnimationActive
      >
        {data.map((d) => (
          <Cell key={d.label} fill={d.color} />
        ))}
      </Pie>
      <Tooltip content={<ChartTooltip suffix={suffix} />} />
    </PieChart>
  </ResponsiveContainer>
);

